            return { net: P - ss - it - pens, tax: it, co: 0.0, it: it };
        }
        S = Math.min(C.SAL * months / 12.0, Math.max(0.0, Pt));
        it = irpf(S - ss - C.EMP_D - pens);
        ist = C.IS * Math.max(0.0, Pt - S);
        keep = P - S - ist;
        return { net: S - ss - it - pens + keep * (1.0 - C.DIV), tax: it + ist, co: ist, it: it };
    }

    // Everything is rebuilt from the decisions; undecided rounds take the template. Nothing is stored.
    function evaluate(dec) {
        var d1 = dec.round1;
        var d2 = dec.round2 || TEMPLATE.round2;
        var d3 = dec.round3 || TEMPLATE.round3;
        var d4 = dec.round4 || TEMPLATE.round4;
        var f = d1.form, c = d1.client, b = d1.bank;
        var t = d2.tool, e = d2.eu, v = d2.vat;
        var i = d3.ins, tm = d3.terms, l = d3.late;
        var x = d4.exp, p = d4.pens, s = d4.base;
        var st7 = f === 'sl' ? 'sl' : 'auto';
        var lateVat = (v === 'later' || b === 'mix') ? 1.0 : 0.0;
        // 2027: fees, losses and costs
        var fees7 = C.MERA[c] + C.OTH[c] + C.EU[e] * C.CAPF[c];
        var err7 = C.ERR[t] * fees7;
        var lost = C.LATE_INV * (1.0 - C.REC[l]);
        var lvat = (l === 'claim' || v === 'recc') ? 0.0 : lost * C.VAT;
        var cost7 = C.EXP7 + C.TOOL_C[t] + C.INS_C[i] + C.TERMS_C[tm] + lateVat * C.VAT_C.later * C.VAT * fees7
            + (l === 'claim' ? C.NOTARY : 0.0) + (x === 'inv' ? C.INV_LOSS : 0.0);
        cost7 += st7 === 'sl' ? C.GEST_S + C.CONST : C.GEST_A;
        var P7 = fees7 - err7 - lost - lvat - cost7;
        var fam = x === 'fam' ? C.FAM : 0.0;
        var pens = C.PENS[p];
        var ss7 = st7 === 'auto' ? C.TP * C.TP_M7 : C.TP_M7 * Math.max(C.SOC_MIN, cuota(P7));
        var y7 = yearNet(st7, P7, P7 - fam, ss7, pens, 11.0);
        var y7h = yearNet(st7, P7, P7, ss7, pens, 11.0);
        var gain = (y7h.tax - y7.tax) + (x === 'fam' ? C.FAM_VAT : 0.0) + ((x === 'fam' && st7 === 'sl') ? fam * C.DIV : 0.0);
        var F = y7h.net + pens * C.PENS_V + gain;
        var L = x === 'fam' ? C.P_FAM * (1.0 + C.SANC) * gain : 0.0;
        // the June 2028 bill for 2027 and the reserve that meets it
        var due7 = st7 === 'auto' ? y7.it - 0.15 * (C.MERA[c] + C.OTH[c]) : y7.co;
        var reserve = C.RES[b] * fees7;
        var unf = Math.max(0.0, due7 - reserve);
        // 2028
        var st8 = (f === 'sl' || (f === 'plan' && P7 > C.PLAN_T)) ? 'sl' : 'auto';
        var fees8 = C.MERA8[c] + C.OTH8[c] + C.EU8[e] * C.CAPF[c] + C.LATE8 * (C.KEEP[l] - 1.0);
        var cost8 = C.EXP8 + C.TOOL_C[t] + C.INS_C[i] + lateVat * C.VAT_C.later * C.VAT * fees8 + C.BASE_X[s] + C.ERR[t] * fees8;
        cost8 += st8 === 'sl' ? C.GEST_S : C.GEST_A;
        if (f === 'plan' && st8 === 'sl') { cost8 += C.CONST; }
        var P8 = fees8 - cost8;
        var ss8 = st8 === 'auto' ? C.TP * C.TP_M8 + (12.0 - C.TP_M8) * cuota(P8) : 12.0 * Math.max(C.SOC_MIN, cuota(P8));
        var y8 = yearNet(st8, P8, P8, ss8, 0.0, 12.0);
        var R = y8.net - C.SHOCK * unf;
        // the worst case: a large claim, the unfunded tax bill, a contribution regularisation, money locked away
        var ceff = C.CLAIM * C.TERMS_F[tm] * (st8 === 'sl' ? (1.0 - C.SL_SH) : 1.0);
        var unc = Math.max(0.0, ceff - C.INS_COV[i]) + (i !== 'none' ? C.DED : 0.0);
        var reg = (s === 'min' && st8 === 'auto') ? (12.0 - C.TP_M8) * (cuota(P8) - C.CU_MIN) : 0.0;
        if (s === 'min' && st8 === 'sl') { reg = 12.0 * (Math.max(C.SOC_MIN, cuota(P8)) - C.SOC_MIN); }
        var W = Math.max(0.0, unc + unf + C.BASE_W[s] * reg + (s === 'high' ? C.BASE_W[s] : 0.0) + C.PENS_W[p] * pens);
        var adm = function(st) { return C.ADM[st] + C.TOOL_H[t] + C.EU_H[e] + C.VAT_H[v] + C.ADM_BANK[b]; };
        var H = (Math.max(1.0, adm(st7)) + Math.max(1.0, adm(st8))) / 2.0;
        return {
            F: F, R: R, E: W, H: H, L: L, P7: P7, P8: P8, fees7: fees7, fees8: fees8, tax7: y7.tax, tax8: y8.tax, ss7: ss7, ss8: ss8,
            unf: unf, unc: unc, reg: reg, gain: gain, pad: fam, sl8: st8 === 'sl' ? 1.0 : 0.0,
            padflag: x === 'fam' ? 1.0 : 0.0
        };
    }

    class AutonomaOSociedad2462Adapter extends USF.SimulationAdapter {
