        // Round model. Every decision is re-evaluated from the decision history, so a resubmit is idempotent.
        _computeRound(state) {
            var ds = state.domainState;
            var raw = state.decisions || {};
            var period = state.currentPeriod || 1;
            var saved = ds.dec || {};
            var d = {};
            var k;
            for (k = 1; k <= period; k++) {
                if (raw['round' + k]) { d['round' + k] = raw['round' + k]; }
                else if (k < period && saved['round' + k]) { d['round' + k] = saved['round' + k]; }
            }
            ds.dec = JSON.parse(JSON.stringify(d));
            var rounds = [];
            var periods = [];
            var total = 0.0;
            var cap = 100.0;
            var r, known, q, rub, W, of, orr, oe, oh, pts;
            for (r = 1; r <= period; r++) {
                known = knownUpTo(d, r);
                q = evaluate(known);
                q.t = r;
                rub = this._rubric(known, r);
                W = C.W_OUT[r - 1];
                of = W * C.W_F * clamp((q.F - q.L - C.F_LO) / (C.F_HI - C.F_LO), 0.0, 1.0);
                orr = W * C.W_R * clamp((q.R - C.R_LO) / (C.R_HI - C.R_LO), 0.0, 1.0);
                oe = W * C.W_E * clamp((C.E_HI - q.E) / (C.E_HI - C.E_LO), 0.0, 1.0);
                oh = W * C.W_H * clamp((C.H_HI - q.H) / (C.H_HI - C.H_LO), 0.0, 1.0);
                pts = rub + of + orr + oe + oh;
                total += pts;
                cap = 100.0;
                if (q.padflag > 0) { cap = Math.max(C.CAP_FLOOR, C.CAP_BASE - C.CAPC_W * q.pad); }
                periods.push(q);
                rounds.push({ period: r, rub: rub, of: of, orr: orr, oe: oe, oh: oh, pts: pts, verdictKey: this._verdict(known, r) });
            }
            var last = periods[periods.length - 1];
            ds.rounds = rounds;
            ds.periods = periods;
            ds.padCum = last.padflag > 0 ? last.pad : 0;
            ds.total = total;
            ds.cap = cap;
            var score = this._composite(ds);
            ds.capKeys = [];
            if (last.padflag > 0) { ds.capKeys.push('cap_pad'); }
            ds.performance = { overallScore: score };
            ds.performanceTier = this._tier(score);
            ds.scoreHistory = (ds.scoreHistory || []).slice(0, period - 1);
            ds.scoreHistory[period - 1] = score;
            ds.scoreHistory.length = period;
            return {
                period: period,
                roundPoints: Math.round(rounds[period - 1].pts * 10) / 10,
                F: Math.round(last.F),
                R: Math.round(last.R),
                E: Math.round(last.E),
                H: Math.round(last.H * 10) / 10,
                L: Math.round(last.L),
                score: score,
                overallScore: score
            };
        }

        _rubric(dec, r) {
            var P = C.PTS;
            var d = dec['round' + r];
            var keys = Object.keys(CTRL['round' + r]);
            var s = 0, i;
            for (i = 0; i < keys.length; i++) { s += P[RK[keys[i]]][d[keys[i]]]; }
